const STAGES = [
  { key: 'pending', label: '待投递' },
  { key: 'applied', label: '已投递' },
  { key: 'interview', label: '面试中' },
  { key: 'closed', label: '已结束' }
];
const STAGE_LABEL = STAGES.reduce((acc, s) => { acc[s.key] = s.label; return acc; }, {});
const STAGE_KEYS = STAGES.map((s) => s.key);

const state = {
  records: [],
  filter: 'all',
  editingId: null,
  pendingDeleteId: null
};

const el = {
  stats: document.querySelector('[data-stats]'),
  totalLine: document.querySelector('[data-total-line]'),
  form: document.querySelector('[data-record-form]'),
  formTitle: document.querySelector('[data-form-title]'),
  formError: document.querySelector('[data-form-error]'),
  submitBtn: document.querySelector('[data-submit-btn]'),
  cancelEdit: document.querySelector('[data-cancel-edit]'),
  company: document.querySelector('#field-company'),
  position: document.querySelector('#field-position'),
  applyDate: document.querySelector('#field-date'),
  stage: document.querySelector('#field-stage'),
  note: document.querySelector('#field-note'),
  list: document.querySelector('[data-record-list]'),
  listCount: document.querySelector('[data-list-count]'),
  emptyHint: document.querySelector('[data-empty-hint]'),
  filterBar: document.querySelector('.filter-bar'),
  dialog: document.querySelector('[data-dialog]'),
  dialogTitle: document.querySelector('[data-dialog-title]'),
  dialogText: document.querySelector('[data-dialog-text]'),
  dialogCancel: document.querySelector('[data-dialog-cancel]'),
  dialogConfirm: document.querySelector('[data-dialog-confirm]')
};

function normalizeStage(value) {
  return STAGE_KEYS.indexOf(value) >= 0 ? value : 'pending';
}

function normalizeRecord(raw) {
  const source = raw && typeof raw === 'object' ? raw : {};
  const record = Object.assign({}, source);
  record.id = typeof source.id === 'string' && source.id ? source.id : 'r-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
  record.company = typeof source.company === 'string' ? source.company : '';
  record.position = typeof source.position === 'string' ? source.position : '';
  record.applyDate = typeof source.applyDate === 'string' ? source.applyDate : '';
  record.stage = normalizeStage(source.stage);
  record.note = typeof source.note === 'string' ? source.note : '';
  if (typeof record.createdAt !== 'number') record.createdAt = Date.now();
  return record;
}

function todayString() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return d.getFullYear() + '-' + m + '-' + day;
}

function formatDate(value) {
  if (!value) return '未填写';
  const parts = String(value).split('-');
  if (parts.length === 3) return parts[0] + '年' + Number(parts[1]) + '月' + Number(parts[2]) + '日';
  return value;
}

function countByStage() {
  const counts = { all: state.records.length };
  STAGE_KEYS.forEach((key) => { counts[key] = 0; });
  state.records.forEach((record) => {
    const key = normalizeStage(record.stage);
    counts[key] += 1;
  });
  return counts;
}

function visibleRecords() {
  if (state.filter === 'all') return state.records.slice();
  return state.records.filter((record) => normalizeStage(record.stage) === state.filter);
}

function renderStats() {
  const counts = countByStage();
  el.stats.textContent = '';
  const cards = [{ key: 'all', label: '全部' }].concat(STAGES);
  cards.forEach((card) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'stat-card' + (state.filter === card.key ? ' is-active' : '');
    btn.setAttribute('data-stat', card.key);

    const label = document.createElement('span');
    label.className = 'stat-label';
    label.textContent = card.label;

    const value = document.createElement('span');
    value.className = 'stat-value';
    value.textContent = String(counts[card.key] || 0);

    btn.appendChild(label);
    btn.appendChild(value);
    el.stats.appendChild(btn);
  });

  const parts = STAGES.map((s) => s.label + ' ' + (counts[s.key] || 0)).join(' · ');
  el.totalLine.textContent = '共 ' + counts.all + ' 条记录（' + parts + '）';
}

function renderFilters() {
  const chips = el.filterBar.querySelectorAll('[data-filter]');
  Array.prototype.forEach.call(chips, (chip) => {
    const key = chip.getAttribute('data-filter');
    chip.classList.toggle('is-active', key === state.filter);
  });
}

function buildRecordItem(record) {
  const li = document.createElement('li');
  li.className = 'record-item';
  li.setAttribute('data-id', record.id);

  const top = document.createElement('div');
  top.className = 'record-top';

  const titleWrap = document.createElement('div');
  const company = document.createElement('p');
  company.className = 'record-company';
  company.textContent = record.company || '（未填写公司）';
  const position = document.createElement('p');
  position.className = 'record-position';
  position.textContent = record.position || '（未填写岗位）';
  titleWrap.appendChild(company);
  titleWrap.appendChild(position);

  const stageKey = normalizeStage(record.stage);
  const badge = document.createElement('span');
  badge.className = 'stage-badge stage-' + stageKey;
  badge.textContent = STAGE_LABEL[stageKey];

  top.appendChild(titleWrap);
  top.appendChild(badge);

  const meta = document.createElement('div');
  meta.className = 'record-meta';
  const dateSpan = document.createElement('span');
  dateSpan.textContent = '投递日期：' + formatDate(record.applyDate);
  meta.appendChild(dateSpan);

  li.appendChild(top);
  li.appendChild(meta);

  if (record.note) {
    const note = document.createElement('p');
    note.className = 'record-note';
    note.textContent = record.note;
    li.appendChild(note);
  }

  const actions = document.createElement('div');
  actions.className = 'record-actions';

  const editBtn = document.createElement('button');
  editBtn.type = 'button';
  editBtn.className = 'btn btn-ghost btn-small';
  editBtn.setAttribute('data-action', 'edit');
  editBtn.setAttribute('data-id', record.id);
  editBtn.textContent = '编辑';

  const delBtn = document.createElement('button');
  delBtn.type = 'button';
  delBtn.className = 'btn btn-danger btn-small';
  delBtn.setAttribute('data-action', 'delete');
  delBtn.setAttribute('data-id', record.id);
  delBtn.textContent = '删除';

  actions.appendChild(editBtn);
  actions.appendChild(delBtn);
  li.appendChild(actions);

  return li;
}

function renderList() {
  const records = visibleRecords();
  el.list.textContent = '';
  records.forEach((record) => {
    el.list.appendChild(buildRecordItem(record));
  });

  const total = state.records.length;
  el.listCount.textContent = state.filter === 'all'
    ? total + ' 条'
    : records.length + ' / ' + total + ' 条';

  if (records.length === 0) {
    el.emptyHint.hidden = false;
    el.emptyHint.textContent = total === 0
      ? '还没有投递记录，先在上方添加第一条吧。'
      : '当前筛选（' + STAGE_LABEL[state.filter] + '）下没有记录。';
  } else {
    el.emptyHint.hidden = true;
    el.emptyHint.textContent = '';
  }
}

function render() {
  renderStats();
  renderFilters();
  renderList();
}

function showFormError(message) {
  if (message) {
    el.formError.textContent = message;
    el.formError.hidden = false;
  } else {
    el.formError.textContent = '';
    el.formError.hidden = true;
  }
}

function resetForm() {
  state.editingId = null;
  el.form.reset();
  el.applyDate.value = todayString();
  el.stage.value = 'pending';
  el.formTitle.textContent = '新增投递记录';
  el.submitBtn.textContent = '保存记录';
  el.cancelEdit.hidden = true;
  showFormError('');
}

function fillForm(record) {
  state.editingId = record.id;
  el.company.value = record.company;
  el.position.value = record.position;
  el.applyDate.value = record.applyDate;
  el.stage.value = normalizeStage(record.stage);
  el.note.value = record.note;
  el.formTitle.textContent = '编辑投递记录';
  el.submitBtn.textContent = '保存修改';
  el.cancelEdit.hidden = false;
  showFormError('');
}

async function persist(nextRecords) {
  const current = await appStore.getState();
  const next = Object.assign({}, current, { records: nextRecords });
  await appStore.setState(next);
}

async function handleSubmit(event) {
  event.preventDefault();
  const company = el.company.value.trim();
  const position = el.position.value.trim();
  const applyDate = el.applyDate.value;
  const stage = normalizeStage(el.stage.value);
  const note = el.note.value.trim();

  if (!company) {
    showFormError('请填写公司名称。');
    el.company.focus();
    return;
  }
  if (!position) {
    showFormError('请填写岗位名称。');
    el.position.focus();
    return;
  }

  const editingId = state.editingId;
  let nextRecords;
  if (editingId) {
    nextRecords = state.records.map((record) => {
      if (record.id !== editingId) return record;
      return Object.assign({}, record, {
        company: company,
        position: position,
        applyDate: applyDate,
        stage: stage,
        note: note
      });
    });
  } else {
    const newRecord = normalizeRecord({
      id: 'r-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8),
      company: company,
      position: position,
      applyDate: applyDate,
      stage: stage,
      note: note,
      createdAt: Date.now()
    });
    nextRecords = state.records.concat([newRecord]);
  }

  try {
    await persist(nextRecords);
  } catch (error) {
    showFormError('保存失败，请重试。你的输入已保留。');
    return;
  }

  state.records = nextRecords;
  resetForm();
  render();
}

function openDeleteDialog(record) {
  state.pendingDeleteId = record.id;
  el.dialogTitle.textContent = '确认删除';
  el.dialogText.textContent = '确定要删除「' + (record.company || '未填写公司') + ' · ' + (record.position || '未填写岗位') + '」这条投递记录吗？删除后无法恢复。';
  el.dialog.hidden = false;
  el.dialogConfirm.focus();
}

function closeDeleteDialog() {
  state.pendingDeleteId = null;
  el.dialog.hidden = true;
}

async function confirmDelete() {
  const id = state.pendingDeleteId;
  if (!id) {
    closeDeleteDialog();
    return;
  }
  const nextRecords = state.records.filter((record) => record.id !== id);
  try {
    await persist(nextRecords);
  } catch (error) {
    closeDeleteDialog();
    showFormError('删除失败，请重试。');
    return;
  }
  state.records = nextRecords;
  if (state.editingId === id) resetForm();
  closeDeleteDialog();
  render();
}

function handleListClick(event) {
  const target = event.target.closest('[data-action]');
  if (!target) return;
  const action = target.getAttribute('data-action');
  const id = target.getAttribute('data-id');
  const record = state.records.filter((item) => item.id === id)[0];
  if (!record) return;

  if (action === 'edit') {
    fillForm(record);
    if (typeof el.company.scrollIntoView === 'function') {
      el.company.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
    el.company.focus();
  } else if (action === 'delete') {
    openDeleteDialog(record);
  }
}

function handleFilterClick(event) {
  const chip = event.target.closest('[data-filter]');
  if (!chip) return;
  const key = chip.getAttribute('data-filter');
  state.filter = key === 'all' || STAGE_KEYS.indexOf(key) >= 0 ? key : 'all';
  render();
}

function handleStatsClick(event) {
  const card = event.target.closest('[data-stat]');
  if (!card) return;
  const key = card.getAttribute('data-stat');
  state.filter = key === 'all' || STAGE_KEYS.indexOf(key) >= 0 ? key : 'all';
  render();
}

async function init() {
  const stored = await appStore.getState();
  const rawRecords = stored && Array.isArray(stored.records) ? stored.records : [];
  state.records = rawRecords.map(normalizeRecord);

  el.form.addEventListener('submit', handleSubmit);
  el.cancelEdit.addEventListener('click', () => {
    resetForm();
  });
  el.list.addEventListener('click', handleListClick);
  el.filterBar.addEventListener('click', handleFilterClick);
  el.stats.addEventListener('click', handleStatsClick);
  el.dialogCancel.addEventListener('click', closeDeleteDialog);
  el.dialogConfirm.addEventListener('click', confirmDelete);
  el.dialog.addEventListener('click', (event) => {
    if (event.target === el.dialog) closeDeleteDialog();
  });
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && !el.dialog.hidden) closeDeleteDialog();
  });

  resetForm();
  render();
}

await init();

