:root {
  --brand: #1d5fd6;
  --brand-dark: #16489f;
  --brand-soft: #e8f0fe;
  --brand-line: #c9dcfb;
  --ink: #16233a;
  --ink-soft: #5a6b85;
  --surface: #ffffff;
  --surface-alt: #f4f8ff;
  --danger: #d64545;
  --danger-dark: #b53636;
  --radius: 14px;
  --shadow: 0 6px 18px rgba(29, 95, 214, 0.10);
}

#app {
  min-height: 100vh;
  background: linear-gradient(180deg, #eaf2ff 0%, #f7fbff 45%, #ffffff 100%);
  color: var(--ink);
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  -webkit-text-size-adjust: 100%;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 720px;
  margin: 0 auto;
  padding: 20px 14px 48px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.app-header {
  padding: 6px 4px 2px;
}

.app-title {
  margin: 0;
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--brand-dark);
}

.app-subtitle {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
}

.panel {
  background: var(--surface);
  border: 1px solid var(--brand-line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px;
}

.panel-title {
  margin: 0 0 12px;
  font-size: 16px;
  font-weight: 600;
  color: var(--brand-dark);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.stat-card {
  appearance: none;
  border: 1px solid var(--brand-line);
  background: var(--surface-alt);
  border-radius: 12px;
  padding: 10px 12px;
  text-align: left;
  cursor: pointer;
  font: inherit;
  color: var(--ink);
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
}

.stat-card:hover {
  background: var(--brand-soft);
}

.stat-card:active {
  transform: scale(0.98);
}

.stat-card.is-active {
  background: var(--brand);
  border-color: var(--brand);
  color: #ffffff;
}

.stat-label {
  display: block;
  font-size: 13px;
  opacity: 0.9;
}

.stat-value {
  display: block;
  font-size: 22px;
  font-weight: 700;
  line-height: 1.2;
}

.stats-total {
  margin: 12px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
}

.record-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.field-full {
  grid-column: 1 / -1;
}

.field label {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-soft);
}

.field input,
.field select,
.field textarea {
  width: 100%;
  font: inherit;
  color: var(--ink);
  background: var(--surface-alt);
  border: 1px solid var(--brand-line);
  border-radius: 10px;
  padding: 10px 12px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}

.field textarea {
  resize: vertical;
  min-height: 76px;
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  border-color: var(--brand);
  background: var(--surface);
  box-shadow: 0 0 0 3px rgba(29, 95, 214, 0.16);
}

.field input::placeholder,
.field textarea::placeholder {
  color: #9aa9c0;
}

.form-error {
  grid-column: 1 / -1;
  margin: 0;
  padding: 8px 12px;
  border-radius: 10px;
  background: #fdecec;
  border: 1px solid #f3c4c4;
  color: var(--danger-dark);
  font-size: 13px;
}

.form-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  appearance: none;
  font: inherit;
  font-weight: 600;
  border-radius: 10px;
  padding: 10px 18px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease, transform 0.1s ease;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background: var(--brand);
  color: #ffffff;
}

.btn-primary:hover {
  background: var(--brand-dark);
}

.btn-ghost {
  background: var(--surface);
  color: var(--brand-dark);
  border-color: var(--brand-line);
}

.btn-ghost:hover {
  background: var(--brand-soft);
}

.btn-danger {
  background: var(--danger);
  color: #ffffff;
}

.btn-danger:hover {
  background: var(--danger-dark);
}

.btn-small {
  padding: 6px 12px;
  font-size: 13px;
  border-radius: 8px;
}

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.list-head .panel-title {
  margin-bottom: 0;
}

.list-count {
  font-size: 13px;
  color: var(--ink-soft);
}

.filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 12px 0 14px;
}

.chip {
  appearance: none;
  font: inherit;
  font-size: 13px;
  padding: 6px 14px;
  border-radius: 999px;
  border: 1px solid var(--brand-line);
  background: var(--surface-alt);
  color: var(--brand-dark);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.chip:hover {
  background: var(--brand-soft);
}

.chip.is-active {
  background: var(--brand);
  border-color: var(--brand);
  color: #ffffff;
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.record-item {
  border: 1px solid var(--brand-line);
  border-radius: 12px;
  background: var(--surface-alt);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.record-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.record-company {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--ink);
  word-break: break-word;
}

.record-position {
  margin: 2px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
  word-break: break-word;
}

.stage-badge {
  flex: none;
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid transparent;
  white-space: nowrap;
}

.stage-pending {
  background: #eef1f6;
  color: #4a5a72;
  border-color: #d8dfea;
}

.stage-applied {
  background: var(--brand-soft);
  color: var(--brand-dark);
  border-color: var(--brand-line);
}

.stage-interview {
  background: #fff4e0;
  color: #9a6412;
  border-color: #f5dcae;
}

.stage-closed {
  background: #f0f1f3;
  color: #6b7280;
  border-color: #dde0e5;
}

.record-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  font-size: 13px;
  color: var(--ink-soft);
}

.record-note {
  margin: 0;
  font-size: 13px;
  color: var(--ink);
  background: var(--surface);
  border: 1px dashed var(--brand-line);
  border-radius: 10px;
  padding: 8px 10px;
  white-space: pre-wrap;
  word-break: break-word;
}

.record-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.empty-hint {
  margin: 4px 0 0;
  padding: 18px 12px;
  text-align: center;
  font-size: 14px;
  color: var(--ink-soft);
  background: var(--surface-alt);
  border: 1px dashed var(--brand-line);
  border-radius: 12px;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(16, 32, 58, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 360px;
  background: var(--surface);
  border-radius: var(--radius);
  border: 1px solid var(--brand-line);
  box-shadow: 0 18px 40px rgba(16, 32, 58, 0.28);
  padding: 18px;
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
  color: var(--brand-dark);
}

.dialog-text {
  margin: 0 0 16px;
  font-size: 14px;
  color: var(--ink-soft);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 520px) {
  .app-shell {
    padding: 16px 12px 40px;
  }

  .app-title {
    font-size: 21px;
  }

  .record-form {
    grid-template-columns: minmax(0, 1fr);
  }

  .stats-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .btn {
    padding: 10px 14px;
  }
}
